const resp=$input.first().json;
const text=resp.content?.[0]?.text||'{}';
let queries=[];
try{queries=JSON.parse(text.replace(/```json|```/g,'').trim()).queries||[];}catch(e){queries=[{name:'Parse Error',query:'error',data_source:'wazuh',mitre_technique:'N/A'}];}
const huntId=`HUNT-${Date.now()}`;
return[{json:{hunt_id:huntId,hypothesis:$('Hunt Trigger').first().json?.raw_data?.hypothesis||'Unknown',queries,query_count:queries.length,hunter:$('Hunt Trigger').first().json?.analyst||'unknown',started_at:new Date().toISOString()}}];

